const item = $input.first().json;
let mediaUrls = [];
if (typeof item.media_paths === 'string') {
  try { mediaUrls = JSON.parse(item.media_paths); } catch(e) {}
} else if (Array.isArray(item.media_paths)) {
  mediaUrls = item.media_paths;
}
return mediaUrls.map((url, idx) => ({
  json: {
    image_url: url,
    index: idx,
    post_id: item.id,
    topic: item.topic,
    caption: item.linkedin_caption
  }
}));

const items = $input.all();
const originalSlides = $('Preparar Lista de Slides').all();

return items.map((item, idx) => {
  const uploadUrl = item.json.value.uploadMechanism['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest'].uploadUrl;
  const assetUrn = item.json.value.asset;
  const orig = originalSlides[idx] ? originalSlides[idx].json : {};
  return {
    json: {
      image_url: orig.image_url,
      upload_url: uploadUrl,
      asset_urn: assetUrn,
      post_id: orig.post_id,
      topic: orig.topic,
      caption: orig.caption
    }
  };
});

const items = $input.all();
const slidesInfo = $('Anexar UploadUrl ao Slide').all();

const mediaArray = slidesInfo.map(item => ({
  status: 'READY',
  media: item.json.asset_urn
}));

const firstItem = slidesInfo[0].json;
let caption = (firstItem.caption || firstItem.topic || '').replace(/-\s*/g, '').replace(/-\s*/g, '');

const body = {
  author: 'urn:li:person:sezTQL8IJe',
  lifecycleState: 'PUBLISHED',
  specificContent: {
    'com.linkedin.ugc.ShareContent': {
      shareCommentary: {
        text: caption
      },
      shareMediaCategory: 'IMAGE',
      media: mediaArray
    }
  },
  visibility: {
    'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC'
  }
};

return [{ json: { linkedin_body: body, post_id: firstItem.post_id } }];
